The button below renders "Off". What happens when it is clicked?

```jsx
class Toggle extends React.Component {
  state = { on: false };

  handleClick() {
    this.setState({ on: !this.state.on });
  }

  render() {
    return (
      <button onClick={this.handleClick}>
        {this.state.on ? 'On' : 'Off'}
      </button>
    );
  }
}
```

The user clicks the "Shipping" header (index 0). What does the accordion show?

```jsx
function Accordion({ sections }) {
  const [openIndex, setOpenIndex] = useState(null);
  return sections.map((s, i) => (
    <section key={s.id}>
      <button onClick={() => setOpenIndex(openIndex === i ? null : i)}>
        {s.title}
      </button>
      {openIndex && openIndex === i && <p>{s.body}</p>}
    </section>
  ));
}
// sections: Shipping (index 0), Returns (index 1)
