The app is not wrapped in StrictMode. The user clicks the first todo, which is not done yet. What changes on screen?

```jsx
const TodoItem = memo(function TodoItem({ todo, onToggle }) {
  return (
    <li className={todo.done ? 'done' : ''} onClick={() => onToggle(todo.id)}>
      {todo.title}
    </li>
  );
});

function TodoList({ initialTodos }) {
  const [todos, setTodos] = useState(initialTodos);
  const toggle = useCallback(id => {
    setTodos(prev => prev.map(t => {
      if (t.id === id) t.done = !t.done;
      return t;
    }));
  }, []);
  const left = todos.filter(t => !t.done).length;
  return (
    <>
      <p>{left} left</p>
      <ul>{todos.map(t => <TodoItem key={t.id} todo={t} onToggle={toggle} />)}</ul>
    </>
  );
}
```

