The user clicks the first button twice. What is on screen?

```jsx
function Counters() {
  const [counts, setCounts] = useState([0, 0, 0]);
  const [total, setTotal] = useState(0);

  function increment(i) {
    setCounts(counts.map((c, j) => (j === i ? c + 1 : c)));
    setTotal(counts.reduce((a, b) => a + b, 0));
  }

  return (
    <>
      {counts.map((c, i) => (
        <button key={i} onClick={() => increment(i)}>{c}</button>
      ))}
      <p>Total: {total}</p>
    </>
  );
}
```

