Autoplay requirements: advance every 3 seconds and wrap around; after the user clicks Prev or Next, wait a full 3 seconds before the next automatic move; stop all timers on unmount. `n` is the number of slides. Which version meets every requirement?

```jsx
// Version 1
useEffect(() => {
  const id = setInterval(() => setIndex(i => (i + 1) % n), 3000);
  return () => clearInterval(id);
}, [n]);

// Version 2
useEffect(() => {
  const id = setTimeout(() => setIndex((index + 1) % n), 3000);
  return () => clearTimeout(id);
}, [index, n]);

// Version 3
useEffect(() => {
  setTimeout(() => setIndex((index + 1) % n), 3000);
}, [index, n]);

// Version 4
useEffect(() => {
  const id = setInterval(() => setIndex((index + 1) % n), 3000);
  return () => clearInterval(id);
}, []);
```

There are 5 slides (s0 to s4) and `perView` is 3. The user clicks Next three times. What is visible, and how do you get a seamless wrap?

```jsx
function Carousel({ slides, perView = 3 }) {
  const [index, setIndex] = useState(0);
  const visible = slides.slice(index, index + perView);
  const next = () => setIndex(i => (i + 1) % slides.length);
  // ...
  return (
    <div className="track">
      {visible.map(s => <img key={s.id} src={s.src} alt={s.alt} />)}
    </div>
  );
}
```

The board is a 3 x 3 array of rows, and every move is saved for time travel. X plays the top-left cell, then O plays the centre. The user clicks "Go to start", which shows `history[0]`. What does that board show?

```jsx
const [history, setHistory] = useState([emptyBoard()]); // 3 rows of [null, null, null]
const board = history[history.length - 1];
const xIsNext = history.length % 2 === 1;

function play(r, c) {
  const next = [...board];
  next[r][c] = xIsNext ? 'X' : 'O';
  setHistory([...history, next]);
}
```

For an N x N board, the interviewer asks for a win check that is O(1) per move instead of rescanning the board. X adds +1 and O adds -1 to running totals, and a line is won when the absolute value of its total reaches `n`. Which line replaces `/* ??? */`?

```js
const rows = Array(n).fill(0);
const cols = Array(n).fill(0);
let diag = 0;
let anti = 0;

function move(r, c, player) {
  const v = player === 'X' ? 1 : -1;
  rows[r] += v;
  cols[c] += v;
  /* ??? */
  return [rows[r], cols[c], diag, anti].some(t => Math.abs(t) === n) ? player : null;
}
```
